// Hidden suite for T01, written from the spec before the implementation.
import { describe, expect, it } from "vitest";
import { createLimiter } from "../src/burst-limiter.ts";

describe("createLimiter: counting", () => {
  it("allows exactly limit requests per window", () => {
    const limiter = createLimiter({ limit: 3, windowMs: 1000, grace: 0 });
    const results = [0, 1, 2, 3].map((t) => limiter.check("acme", "eu", t));
    expect(results.map((r) => r.allowed)).toEqual([true, true, true, false]);
    expect(results.map((r) => r.remaining)).toEqual([2, 1, 0, 0]);
    expect(results.every((r) => r.grace === false)).toBe(true);
  });

  it("counts requests anywhere inside one aligned window together", () => {
    const limiter = createLimiter({ limit: 1, windowMs: 1000, grace: 0 });
    expect(limiter.check("acme", "eu", 400).allowed).toBe(true);
    expect(limiter.check("acme", "eu", 999).allowed).toBe(false);
  });

  it("starts a new window exactly at the window end", () => {
    const limiter = createLimiter({ limit: 1, windowMs: 1000, grace: 0 });
    expect(limiter.check("acme", "eu", 500).allowed).toBe(true);
    expect(limiter.check("acme", "eu", 1000)).toEqual({ allowed: true, remaining: 0, grace: false });
  });

  it("keeps regions of one tenant apart", () => {
    const limiter = createLimiter({ limit: 1, windowMs: 1000, grace: 0 });
    expect(limiter.check("acme", "eu", 0).allowed).toBe(true);
    expect(limiter.check("acme", "us", 0).allowed).toBe(true);
    expect(limiter.check("acme", "eu", 1).allowed).toBe(false);
  });

  it("keeps pairs whose parts contain the separator apart", () => {
    const limiter = createLimiter({ limit: 1, windowMs: 1000, grace: 0 });
    expect(limiter.check("a:b", "c", 0).allowed).toBe(true);
    expect(limiter.check("a", "b:c", 0).allowed).toBe(true);
    expect(limiter.check("a\\", "b", 0).allowed).toBe(true);
    expect(limiter.check("a", "\\b", 0).allowed).toBe(true);
  });
});

describe("createLimiter: grace", () => {
  it("grants grace after a quiet previous window", () => {
    const limiter = createLimiter({ limit: 2, windowMs: 1000, grace: 1 });
    expect(limiter.check("acme", "eu", 1000).allowed).toBe(true);
    expect(limiter.check("acme", "eu", 1001).allowed).toBe(true);
    expect(limiter.check("acme", "eu", 1002)).toEqual({ allowed: true, remaining: 0, grace: true });
  });

  it("withholds grace when the previous window was busy", () => {
    const limiter = createLimiter({ limit: 2, windowMs: 1000, grace: 1 });
    limiter.check("acme", "eu", 0);
    limiter.check("acme", "eu", 1);
    expect(limiter.check("acme", "eu", 1000).allowed).toBe(true);
    expect(limiter.check("acme", "eu", 1001).allowed).toBe(true);
    expect(limiter.check("acme", "eu", 1002)).toEqual({ allowed: false, remaining: 0, grace: false });
  });

  it("treats a gap of whole windows as a quiet previous window", () => {
    const limiter = createLimiter({ limit: 2, windowMs: 1000, grace: 1 });
    limiter.check("acme", "eu", 0);
    limiter.check("acme", "eu", 1);
    expect(limiter.check("acme", "eu", 2500).allowed).toBe(true);
    expect(limiter.check("acme", "eu", 2501).allowed).toBe(true);
    expect(limiter.check("acme", "eu", 2502)).toEqual({ allowed: true, remaining: 0, grace: true });
  });

  it("grants grace when the previous window used exactly half the limit", () => {
    const limiter = createLimiter({ limit: 4, windowMs: 1000, grace: 1 });
    limiter.check("acme", "eu", 0);
    limiter.check("acme", "eu", 1);
    for (const t of [1000, 1001, 1002, 1003]) expect(limiter.check("acme", "eu", t).allowed).toBe(true);
    expect(limiter.check("acme", "eu", 1004).grace).toBe(true);
  });

  it("stops granting grace after the configured number", () => {
    const limiter = createLimiter({ limit: 1, windowMs: 1000, grace: 2 });
    const results = [0, 1, 2, 3].map((t) => limiter.check("acme", "eu", t));
    expect(results.map((r) => [r.allowed, r.grace])).toEqual([
      [true, false],
      [true, true],
      [true, true],
      [false, false],
    ]);
  });
});

describe("createLimiter: config", () => {
  it("rejects invalid config with a RangeError", () => {
    expect(() => createLimiter({ limit: 0, windowMs: 1000, grace: 0 })).toThrow(RangeError);
    expect(() => createLimiter({ limit: 1.5, windowMs: 1000, grace: 0 })).toThrow(RangeError);
    expect(() => createLimiter({ limit: 1, windowMs: 0, grace: 0 })).toThrow(RangeError);
    expect(() => createLimiter({ limit: 1, windowMs: 1000, grace: -1 })).toThrow(RangeError);
  });
});
